const item = $input.item.json;

const niche = item.NICHE || 'general';
const title = item.TITLE || 'Artículo sin título';
const keywords = item.KEYWORDS || '';
const language = item.LANGUAGE || 'es';
const langInstruction = language === 'en' ? 'Write the article in English.' : 'Escribe el artículo en español.';

const systemPrompt = `You are an expert SEO content writer specialized in ${niche}. You write complete, well-structured HTML articles optimized for Google AdSense and organic search. Always respond with ONLY the HTML content, no markdown, no explanations, no code blocks.`;

const userPrompt = `${langInstruction}

Write a complete, SEO-optimized article about: "${title}"

Target keywords: ${keywords}

Requirements:
- Length: 1200-1800 words
- Structure: H1 title, introduction (2 paragraphs), 4-6 H2 sections with 2-3 paragraphs each, conclusion
- Include the target keywords naturally throughout
- Use <strong> tags for important terms
- Add a compelling meta description in a <meta> tag at the top
- Include internal linking anchor text suggestions as HTML comments <!-- INTERNAL LINK: [suggested topic] -->
- Niche-specific: ${niche}
- Tone: expert, educational, conversational
- Format: pure HTML (no markdown, no \`\`\`html wrapper)

Start directly with the HTML content.`;

return {
  json: {
    ...item,
    systemPrompt,
    userPrompt
  }
};

const response = $input.item.json;
const prevData = $('Build Prompt').item.json;

let htmlContent = '';

try {
  htmlContent = response.choices[0].message.content || '';
} catch(e) {
  throw new Error('DeepSeek response missing choices: ' + JSON.stringify(response));
}

if (!htmlContent || htmlContent.trim().length < 100) {
  throw new Error('DeepSeek returned empty or too-short content');
}

// Strip markdown code fences if DeepSeek wrapped in ```html
htmlContent = htmlContent
  .replace(/^```html\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

const tokenUsage = response.usage || {};

return {
  json: {
    ROW_NUMBER: prevData.ROW_NUMBER,
    TITLE: prevData.TITLE,
    BLOG_ID: prevData.BLOG_ID,
    NICHE: prevData.NICHE,
    LANGUAGE: prevData.LANGUAGE || 'es',
    HTML_CONTENT: htmlContent,
    TOKENS_USED: tokenUsage.total_tokens || 0,
    GENERATED_AT: new Date().toISOString()
  }
};

// Return HTML_CONTENT to caller workflow
const data = $('Extract HTML Content').item.json;
return {
  json: {
    HTML_CONTENT: data.HTML_CONTENT,
    ROW_NUMBER: data.ROW_NUMBER,
    TITLE: data.TITLE,
    BLOG_ID: data.BLOG_ID,
    NICHE: data.NICHE,
    TOKENS_USED: data.TOKENS_USED
  }
};
